// JoeChallenge — the boss duel against Joe, the Impossible Challenger.
//
// Scripted only: three questions about the type chart, drawn from
// src/data/joe.ts. No navitar is required to play — Joe tests
// knowledge, not the navitar. Scoring: 2 or 3 correct beats him
// (title: Joe's Champion), exactly 1 is a draw (title: Joe's Equal),
// 0 is a loss (costs nothing, rematch anytime). Titles and duel
// stats are local-only, in localStorage — nothing leaves the browser.

import React, { useRef, useState } from 'react';
import { Box, Typography, Paper, Button } from '@mui/material';
import { useNavigate } from 'react-router-dom';
import { useNavitarFightClub } from '../contexts/NavitarFightClub';
import { JOE_INTRO, JOE_QUESTIONS, JOE_TITLES, type JoeQuestion } from '../data/joe';
import { earnTitle } from '../utils/titles';

// Duel stats — attempts, wins and draws, kept in localStorage next to
// the titles. A loss still counts as an attempt, so the line always
// adds up: attempts = wins + draws + losses.
const JOE_STATS_KEY = 'icewall-joe-stats';

interface JoeStats {
  attempts: number;
  wins: number;
  draws: number;
}

function emptyStats(): JoeStats {
  return { attempts: 0, wins: 0, draws: 0 };
}

function loadJoeStats(): JoeStats {
  try {
    const raw = localStorage.getItem(JOE_STATS_KEY);
    if (!raw) return emptyStats();
    const parsed = JSON.parse(raw) as Record<string, unknown>;
    const num = (v: unknown) =>
      typeof v === 'number' && Number.isFinite(v) && v > 0 ? Math.floor(v) : 0;
    return { attempts: num(parsed.attempts), wins: num(parsed.wins), draws: num(parsed.draws) };
  } catch {
    return emptyStats();
  }
}

function recordJoeResult(outcome: 'win' | 'draw' | 'loss'): JoeStats {
  const stats = loadJoeStats();
  stats.attempts += 1;
  if (outcome === 'win') stats.wins += 1;
  if (outcome === 'draw') stats.draws += 1;
  try {
    localStorage.setItem(JOE_STATS_KEY, JSON.stringify(stats));
  } catch {
    // Private mode / quota: the stats still hold for this session.
  }
  return stats;
}

// Shuffles the question bank and takes the first three — a fresh set
// of distinct questions for every duel.
function pickDuelQuestions(): JoeQuestion[] {
  const shuffled = [...JOE_QUESTIONS];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled.slice(0, 3);
}

type DuelOutcome = 'win' | 'draw' | 'loss';

interface DuelResult {
  outcome: DuelOutcome;
  correct: number;
  titleName: string | null;
  titleBlurb: string | null;
  newlyEarned: boolean;
}

const JoeChallenge: React.FC = () => {
  const navigate = useNavigate();
  const { userNavitar } = useNavitarFightClub();
  const [started, setStarted] = useState(false);
  const [questions, setQuestions] = useState<JoeQuestion[]>(() => pickDuelQuestions());
  const [round, setRound] = useState(0);
  const [picked, setPicked] = useState<number | null>(null);
  const [score, setScore] = useState(0);
  const [result, setResult] = useState<DuelResult | null>(null);
  const [stats, setStats] = useState<JoeStats>(() => loadJoeStats());
  // The result is recorded once per duel, in the Next handler after
  // round 3 — a ref guards it so a re-render can never double-count.
  const resultRecordedRef = useRef(false);

  const question = questions[round];
  const isCorrect = picked !== null && picked === question.correctIndex;

  const startDuel = () => {
    setQuestions(pickDuelQuestions());
    setRound(0);
    setPicked(null);
    setScore(0);
    setResult(null);
    resultRecordedRef.current = false;
    setStarted(true);
  };

  const handlePick = (idx: number) => {
    if (picked !== null) return;
    setPicked(idx);
    if (idx === question.correctIndex) setScore(s => s + 1);
  };

  const handleNext = () => {
    if (picked === null) return;
    if (round < 2) {
      setRound(r => r + 1);
      setPicked(null);
      return;
    }
    // Round 3 is done — settle the duel. `score` already includes
    // this round's answer (handlePick counted it on selection).
    if (resultRecordedRef.current) return;
    resultRecordedRef.current = true;
    const correct = score;
    const outcome: DuelOutcome = correct >= 2 ? 'win' : correct === 1 ? 'draw' : 'loss';
    const nextStats = recordJoeResult(outcome);
    setStats(nextStats);
    if (outcome === 'win') {
      const wasNew = earnTitle(JOE_TITLES.win);
      setResult({
        outcome,
        correct,
        titleName: JOE_TITLES.win.name,
        titleBlurb: JOE_TITLES.win.blurb,
        newlyEarned: wasNew,
      });
    } else if (outcome === 'draw') {
      const wasNew = earnTitle(JOE_TITLES.draw);
      setResult({
        outcome,
        correct,
        titleName: JOE_TITLES.draw.name,
        titleBlurb: JOE_TITLES.draw.blurb,
        newlyEarned: wasNew,
      });
    } else {
      setResult({ outcome, correct, titleName: null, titleBlurb: null, newlyEarned: false });
    }
  };

  const resultHeading =
    result?.outcome === 'win'
      ? '🏆 You beat Joe!'
      : result?.outcome === 'draw'
        ? '🤝 A draw with the Impossible Challenger'
        : 'Joe takes this one';

  return (
    <Box sx={{ py: 4 }}>
      <Typography variant="h4" gutterBottom>
        🎙️ Joe — the Impossible Challenger
      </Typography>
      <Typography variant="body1" color="text.secondary" paragraph>
        Judge, announcer, and the last door in the Battle Arena. Three questions, all about the type
        chart — answer two right and you beat him.
      </Typography>

      {userNavitar && (
        <Typography variant="body1" paragraph>
          Joe sizes up {userNavitar.name} and grins. “A fine navitar you&apos;ve got there — but
          this duel is about what <em>you</em> know, not what they can do.”
        </Typography>
      )}

      {!started && (
        <Paper sx={{ p: 3, mb: 3 }}>
          {JOE_INTRO.map(line => (
            <Typography key={line} variant="body1" paragraph>
              “{line}”
            </Typography>
          ))}
          <Button variant="contained" color="secondary" size="large" onClick={startDuel}>
            Start the duel
          </Button>
          <Typography variant="body2" color="text.secondary" sx={{ mt: 2 }}>
            No navitar needed — Joe tests your knowledge of the type chart. A loss costs nothing.
          </Typography>
        </Paper>
      )}

      {started && !result && (
        <Paper sx={{ p: 3, mb: 3 }}>
          <Typography variant="subtitle1" gutterBottom>
            Round {round + 1} of 3
          </Typography>
          <Typography variant="h6" gutterBottom>
            {question.question}
          </Typography>
          {question.options.map((option, idx) => {
            const isPicked = picked === idx;
            const isRightAnswer = idx === question.correctIndex;
            return (
              <Button
                key={option}
                variant={isPicked ? 'contained' : 'outlined'}
                color={picked === null ? 'primary' : isRightAnswer ? 'success' : 'error'}
                fullWidth
                sx={{ mb: 1, justifyContent: 'flex-start', textTransform: 'none' }}
                disabled={picked !== null}
                onClick={() => handlePick(idx)}
              >
                {option}
                {picked !== null && isRightAnswer ? ' ✓' : ''}
                {picked !== null && isPicked && !isRightAnswer ? ' ✗' : ''}
              </Button>
            );
          })}
          {picked !== null && (
            <Box sx={{ mt: 2 }}>
              <Typography variant="body1" gutterBottom>
                {isCorrect ? '✅ Correct!' : '❌ Not quite — the right answer was highlighted.'}
              </Typography>
              <Typography variant="body1" paragraph>
                Joe: “{question.explanation}”
              </Typography>
              <Button variant="contained" onClick={handleNext}>
                {round < 2 ? 'Next round' : 'See the result'}
              </Button>
            </Box>
          )}
        </Paper>
      )}

      {result && (
        <Paper sx={{ p: 3, mb: 3 }}>
          <Typography variant="h5" gutterBottom>
            {resultHeading}
          </Typography>
          <Typography variant="body1" gutterBottom>
            You answered {result.correct} of 3 correctly.
          </Typography>
          {result.outcome === 'win' && result.titleName && (
            <>
              <Typography variant="body1" paragraph>
                🏆 <strong>{result.titleName}</strong> — {result.titleBlurb}
              </Typography>
              <Typography variant="body2" color="text.secondary" paragraph>
                {result.newlyEarned
                  ? 'A new title, added to your Profile.'
                  : 'You already hold this title — it stays on your Profile.'}
              </Typography>
            </>
          )}
          {result.outcome === 'draw' && result.titleName && (
            <>
              <Typography variant="body1" paragraph>
                🤝 <strong>{result.titleName}</strong> — {result.titleBlurb}
              </Typography>
              <Typography variant="body2" color="text.secondary" paragraph>
                {result.newlyEarned
                  ? 'A new title, added to your Profile.'
                  : 'You already hold this title — it stays on your Profile.'}
              </Typography>
            </>
          )}
          {result.outcome === 'loss' && (
            <Typography variant="body1" paragraph>
              It costs nothing — rematch anytime. Study the type chart and come back for him.
            </Typography>
          )}
          <Typography variant="body2" color="text.secondary" paragraph>
            Joe duels: {stats.attempts} attempt{stats.attempts === 1 ? '' : 's'} · {stats.wins} win
            {stats.wins === 1 ? '' : 's'} · {stats.draws} draw{stats.draws === 1 ? '' : 's'}
          </Typography>
          <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
            <Button variant="contained" color="secondary" onClick={startDuel}>
              Play again
            </Button>
            <Button variant="outlined" onClick={() => navigate('/battle')}>
              Back to the Battle Arena
            </Button>
          </Box>
        </Paper>
      )}

      {started && !result && (
        <Typography variant="body2" color="text.secondary" align="center">
          Joe duels so far: {stats.attempts} attempt{stats.attempts === 1 ? '' : 's'} · {stats.wins}{' '}
          win{stats.wins === 1 ? '' : 's'} · {stats.draws} draw
          {stats.draws === 1 ? '' : 's'}
        </Typography>
      )}
    </Box>
  );
};

export default JoeChallenge;
